data.pageSchema:
{
  "renderer": "page",
  "body": [
    {
      "renderer": "form",
      "controls": [
        {
          "renderer": "input",
          "name": "searchPath",
          "placeholder": "path",
          "type": "text",
          "rules": []
        },
        {
          "renderer": "input",
          "name": "searchTitle",
          "placeholder": "title",
          "type": "text",
          "rules": []
        },
        {
          "renderer": "action",
          "text": "搜索",
          "actionType": "submit",
          "body": {}
        }
      ],
      "submitType": "target",
      "inline": true,
      "target": "MockTable"
    },
    {
      "renderer": "table",
      "initApi": {
        "url": "/api/mocks",
        "method": "get",
        "cached": false,
        "params": {
          "path": "${searchPath}",
          "title": "${searchTitle}"
        }
      },
      "columns": [
        {
          "label": "id",
          "name": "id",
          "width": "-",
          "sortable": false,
          "fixed": false,
          "type": "-",
          "align": "none"
        },
        {
          "label": "method",
          "name": "method",
          "width": "-",
          "sortable": false,
          "fixed": false,
          "type": "-",
          "align": "none"
        },
        {
          "label": "标题",
          "name": "title",
          "width": "-",
          "sortable": false,
          "fixed": false,
          "type": "-",
          "align": "none"
        },
        {
          "label": "路径",
          "name": "path",
          "width": "-",
          "sortable": false,
          "fixed": false,
          "type": "-",
          "align": "none"
        },
        {
          "label": "创建人",
          "name": "createdBy",
          "width": "-",
          "sortable": false,
          "fixed": false,
          "type": "-",
          "align": "none"
        },
        {
          "label": "描述",
          "name": "description",
          "width": "-",
          "sortable": false,
          "fixed": false,
          "type": "-",
          "align": "none"
        },
        {
          "label": "创建日期",
          "name": "createdAt",
          "width": "-",
          "sortable": false,
          "fixed": false,
          "type": "-",
          "align": "none"
        },
        {
          "label": "操作",
          "width": "-",
          "sortable": false,
          "fixed": false,
          "type": "-",
          "align": "none",
          "body": [
            {
              "renderer": "action",
              "text": "修改",
              "size": "small",
              "actionType": "drawer",
              "body": {
                "body": {
                  "renderer": "form",
                  "controls": [
                    {
                      "renderer": "input",
                      "name": "title",
                      "label": "标题",
                      "requiredOn": "1===1",
                      "placeholder": "test",
                      "type": "text",
                      "rules": []
                    },
                    {
                      "renderer": "input",
                      "name": "path",
                      "label": "路径",
                      "requiredOn": "1===1",
                      "placeholder": "/test",
                      "type": "text",
                      "rules": []
                    },
                    {
                      "renderer": "input",
                      "name": "delay",
                      "label": "延迟",
                      "placeholder": "2000",
                      "type": "text",
                      "rules": []
                    },
                    {
                      "renderer": "monaco",
                      "name": "schema",
                      "language": "javascript",
                      "label": "协议",
                      "requiredOn": "1===1",
                      "rules": [],
                      "defaultValue": "function({_req}) {}"
                    }
                  ],
                  "name": "UpdateForm",
                  "actionApi": {
                    "url": "/api/mock",
                    "method": "put",
                    "params": {
                      "*": "*"
                    }
                  },
                  "reload": "MockTable"
                },
                "footer": [
                  {
                    "renderer": "action",
                    "text": "提交",
                    "actionType": "submit",
                    "triggered": "UpdateForm",
                    "body": {}
                  }
                ]
              },
              "plain": true
            },
            {
              "renderer": "action",
              "text": "删除",
              "plain": true,
              "actionType": "ajax",
              "actionApi": {
                "url": "/api/mock/${id}",
                "method": "delete",
                "params": {}
              },
              "reload": "MockTable",
              "body": {},
              "size": "small",
              "type": "danger"
            }
          ]
        }
      ],
      "actions": [
        {
          "renderer": "action",
          "text": "新增",
          "plain": true,
          "size": "small",
          "actionType": "drawer",
          "body": {
            "body": [
              {
                "renderer": "form",
                "controls": [
                  {
                    "renderer": "radio",
                    "name": "method",
                    "label": "方法",
                    "defaultValue": "get",
                    "options": [
                      {
                        "text": "get",
                        "value": "get",
                        "disabledOn": ""
                      },
                      {
                        "text": "post",
                        "value": "post",
                        "disabledOn": ""
                      },
                      {
                        "text": "delete",
                        "value": "delte",
                        "disabledOn": ""
                      },
                      {
                        "text": "put",
                        "value": "put",
                        "disabledOn": ""
                      }
                    ],
                    "rules": [],
                    "requiredOn": "1===1",
                    "type": "button"
                  },
                  {
                    "renderer": "input",
                    "name": "title",
                    "label": "标题",
                    "requiredOn": "1===1",
                    "type": "text",
                    "rules": [],
                    "placeholder": "测试"
                  },
                  {
                    "renderer": "input",
                    "name": "path",
                    "label": "路径",
                    "requiredOn": "1===1",
                    "type": "text",
                    "rules": [],
                    "placeholder": "/test"
                  },
                  {
                    "renderer": "input",
                    "name": "delay",
                    "label": "延迟",
                    "placeholder": "2000",
                    "type": "text",
                    "rules": []
                  },
                  {
                    "renderer": "input",
                    "name": "description",
                    "label": "描述",
                    "type": "text",
                    "rules": [],
                    "placeholder": "首次模拟测试"
                  },
                  {
                    "renderer": "monaco",
                    "name": "schema",
                    "language": "javascript",
                    "label": "协议",
                    "requiredOn": "1===1",
                    "rules": [],
                    "defaultValue": "function({_req}) {}"
                  }
                ],
                "name": "CreateForm",
                "actionApi": {
                  "url": "/api/mock",
                  "method": "post",
                  "params": {
                    "*": "*"
                  }
                },
                "reload": "MockTable"
              }
            ],
            "footer": [
              {
                "renderer": "action",
                "text": "提交",
                "actionType": "submit",
                "triggered": "CreateForm",
                "body": {}
              }
            ]
          },
          "type": "success"
        }
      ],
      "name": "MockTable",
      "title": "列表"
    }
  ]
}
